import{_ as t}from"./chunks/hub.pc.en.Cb61JjFk.js";import{_ as o}from"./chunks/hub-robots.pc.en.Du0Wyhqd.js";import{_ as n}from"./chunks/home-status.pc.en.KhsLj-pc.js";import{_ as s,o as i,c as a,a5 as r}from"./chunks/framework.D47SInms.js";const d="/RBQ/nightly/images/app/hub-add-robot.pc.en.png",y=JSON.parse('{"title":"Connection","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/connection.md","filePath":"manual/gui/connection.md","lastUpdated":1791600043000}'),c={name:"manual/gui/connection.md"};function h(l,e,p,b,u,m){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="connection" tabindex="-1">Connection <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;Connection&quot;">​</a></h1><p>The <strong>hub</strong> decides <em>which robot the app talks to</em>. It is the first screen you see after startup. The robot name and connection state sit at the top left, and the <code>Control</code> button at the bottom right opens the control home once the robot is connected — before that it reads <code>Opens once connected</code>. Nothing on these screens is sent to the robot itself.</p><p>On the very first start — no saved robot and no account — the app opens the <strong>Access code</strong> screen instead. Press <code>Skip</code> to go straight to the hub, and the app starts looking for a robot on the robot&#39;s network on its own.</p><h2 id="status-line" tabindex="-1">Status line <a class="header-anchor" href="#status-line" aria-label="Permalink to &quot;Status line&quot;">​</a></h2><p><img src="'+t+'" alt="The hub status line"></p><p>The robot name has a colored dot in front and the state after it:</p><table tabindex="0"><thead><tr><th>Text</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Connect to the robot&#39;s WiFi</code></td><td>No robot is saved yet</td></tr><tr><td><code>Not connected</code></td><td>A robot is selected but not connected</td></tr><tr><td><code>Connecting…</code></td><td>A connection attempt is in progress</td></tr><tr><td><code>Connected</code> · route</td><td>The app is talking to the robot — the route is <code>local network</code>, <code>WAN</code>, or <code>remote</code>, and the battery follows</td></tr><tr><td><code>Connection failed</code> · reason</td><td>The attempt failed — press <code>Reconnect</code></td></tr><tr><td><code>Not on the robot&#39;s WiFi</code></td><td>The robot is on its own network, but this device is on another one</td></tr><tr><td><code>Remote — access code needed</code></td><td>A remote robot is selected but the access code is not stored — press <code>Enter code</code></td></tr></tbody></table><p>When the device is on the wrong network the line names the robot&#39;s WiFi if the app knows it (<em>Robot WiFi(SSID) — please switch to it</em>). On Linux desktop and Steam Deck, the <code>Switch WiFi</code> button next to it joins that network directly, or opens the network list. On Android, <code>WiFi settings</code> opens the system Wi-Fi screen.</p><h2 id="selecting-a-robot" tabindex="-1">Selecting a robot <a class="header-anchor" href="#selecting-a-robot" aria-label="Permalink to &quot;Selecting a robot&quot;">​</a></h2><p><img src="'+o+'" alt="Select robot"></p><p>Tap the robot name (▾) to open <strong>Select robot</strong>. It lists the robots saved on this device, plus the robots assigned to your account while you are logged in. A robot that is both appears once, matched by serial number. Each row shows the serial, the route (<code>local network</code> with the WiFi name, <code>WAN</code>, or <code>remote</code>), and when you last used it. Tap a row to connect.</p><p>The dot on each row shows the robot&#39;s state: green = connected, blue = on (its WiFi is in range), gray = off or unknown.</p><ul><li><strong>Linux desktop / Steam Deck</strong>: the list scans nearby WiFi every time it opens, and <code>Refresh</code> scans again; while the scan runs the dots stay gray rather than showing the previous result (a scan can take up to 15 seconds). Tapping a robot whose WiFi is not in range does not connect — the row reads <em>No signal from the robot&#39;s WiFi</em>. If the robot&#39;s WiFi is saved on the device and in range, the app switches to it before connecting, and the status line names the network it is switching to. If it cannot switch, a dialog says why (<em>Can&#39;t find the robot&#39;s WiFi</em>, <em>WiFi password needed</em>, <em>Couldn&#39;t switch to the robot&#39;s WiFi</em>) and the previous robot stays selected. A network whose password was never entered cannot be joined this way — join it once with <code>Select WiFi</code>.</li><li><strong>Android / iOS</strong>: the app cannot read or change Wi-Fi, so the dot is only green or gray. Switch in the system settings; the status line tells you which network to pick.</li><li>A robot that is also assigned to your account connects directly if it answers on its local network, and remotely if it does not.</li></ul><p>The slider icon on a row opens that robot&#39;s profile, where you can change its <code>Name</code> or delete it with the trash icon. Deleting removes the robot from this device only — server assignments are handled in the dashboard. Remote-only robots have no profile to edit.</p><p>At the bottom, <code>Simulator</code> (<code>In-app physics sim</code>) opens the control home with the in-app simulator instead of a robot, and <code>Add robot</code> opens the screen below.</p><p>The simulator has ten courses set on construction sites and mountains. Tap <code>Level</code> in the tool row at the bottom to open the <code>Sim levels</code> list; cleared levels show ✓ and your best time. Courses float in the air — if the robot falls, it restarts at the last gate it passed. Pass every gate in order — the next one is shown brighter and the top of the screen counts them — then stand on the finish pad to clear the level. A teal gate only counts if the robot passes it sideways while facing the arrow. The robot is always walking, so just push the joystick; set how fast with the maximum speed in <code>Drive</code>. Pick the view from the drop-down at the top center: <code>Third person</code>, <code>First person · front</code>, <code>First person · rear</code> or <code>Stairs view</code>. The first-person views look from the robot&#39;s front or rear, and <code>Stairs view</code> combines the front, rear and belly cameras with the joint pose, as on the robot. <code>Reset</code> restarts the level from the beginning.</p><h2 id="adding-a-robot" tabindex="-1">Adding a robot <a class="header-anchor" href="#adding-a-robot" aria-label="Permalink to &quot;Adding a robot&quot;">​</a></h2><p><img src="'+d+'" alt="Add robot"></p><p><strong>Add robot</strong> offers the ways to reach a robot. Once a robot answers, it is saved by its serial number and the app returns to the hub.</p><h3 id="robot-wifi" tabindex="-1">Robot WiFi <a class="header-anchor" href="#robot-wifi" aria-label="Permalink to &quot;Robot WiFi&quot;">​</a></h3><p>Join the robot&#39;s WiFi (AP) and the app finds it — on its own network the robot always sits at <code>192.168.0.10</code>. The check runs when the screen opens (unless a robot is already connected) and again with <code>Check again</code>. A new robot is named after the WiFi it was found on; rename it from its profile.</p><ul><li><code>Select WiFi</code> (Linux desktop / Steam Deck) opens the in-app network list. The app checks for the robot again when you close it. A saved network shows a spinner and <code>Connecting…</code> on its row while it joins.</li><li><code>WiFi settings</code> (Android) opens the system Wi-Fi screen.</li><li>If nothing answers: <em>No robot answered — check the robot&#39;s power and that this device is on the robot&#39;s AP.</em></li><li>If the robot found is the one already connected, the app says so instead of adding it again — switch to the other robot&#39;s WiFi and check again.</li></ul><p>In the browser (web) build, this card just says <em>The app (APK/desktop) searches automatically.</em></p><h3 id="connect-by-address" tabindex="-1">Connect by address <a class="header-anchor" href="#connect-by-address" aria-label="Permalink to &quot;Connect by address&quot;">​</a></h3><p>The browser (web) build, the desktop app and Steam Deck also offer <strong>Connect by address</strong>, for a robot behind a router, the simulator on this PC, or a robot with a public IP.</p><ul><li><code>local network</code> — enter the <code>Robot IP</code> (preset to <code>192.168.0.10</code>). <code>Connect</code> first checks that a robot answers at that address. If none does, nothing is saved (<em>No robot responded at this address — check the IP and robot power</em>).</li><li><code>Local</code> — connects to the simulator running on this PC (<code>127.0.0.1</code>). It is checked and saved the same way as <code>local network</code>, so start the simulator first. Steam Deck, which cannot run the simulator, does not show it.</li><li><code>WAN</code> — enter the <code>Public IP or domain</code>. If the robot has a WebRTC token set, enter the same value in <code>WebRTC token (only if set on the robot)</code>. Ports 8080 and 8081 must be reachable from your network.</li></ul><p>The address takes effect only if you opened the page at <code>localhost</code> on the PC that runs the proxy. From another device the app shows <em>The proxy could not switch the target — check that you opened this page via localhost on this PC.</em> — restart the proxy with <code>--robot &lt;new IP&gt;</code> instead.</p><h3 id="access-code" tabindex="-1">Access code <a class="header-anchor" href="#access-code" aria-label="Permalink to &quot;Access code&quot;">​</a></h3><p><code>Enter access code</code> opens the keypad. Enter the 4-digit code from the dashboard one time, and the robots assigned to your account show up in <strong>Select robot</strong> and connect remotely over LTE from then on. The robot does not need a public IP.</p><p>The <strong>Profile</strong> button at the top right shows the account and the number of <code>assigned robots</code>. <code>Log out</code> drops the account&#39;s remote robots from the list. Robots saved on this device stay.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The access code is a credential. Do not share it, and use <code>Log out</code> on a shared device.</p></div><h2 id="automatic-connection" tabindex="-1">Automatic connection <a class="header-anchor" href="#automatic-connection" aria-label="Permalink to &quot;Automatic connection&quot;">​</a></h2><p>The app connects on its own in these cases:</p><ul><li><strong>Start-up</strong> — the app checks the robot&#39;s network first. If a robot answers, it is added (or updated) and connected, and the app skips the hub and opens the control home. If none answers, the desktop app — not Steam Deck — connects to a MuJoCo simulator running on the same PC, and if there is no simulator either, it selects the robot you used most recently. On Linux desktop and Steam Deck, if that robot&#39;s WiFi is known and this device is on another network, the app asks before joining it (<em>Switch to the robot&#39;s WiFi?</em>): <code>Switch WiFi</code> joins the robot&#39;s network, <code>No</code> keeps the network you are on — choose <code>No</code> while you are downloading a software update. After <code>No</code>, start-up leaves the network alone until you restart the app; picking the robot from <strong>Select robot</strong> still switches.</li><li><strong>Network change</strong> — when the device joins a robot&#39;s WiFi, the app checks the robot&#39;s serial number and connects to it, adding it to the list if it is new. This also moves a remote connection to the direct one when you come within range.</li></ul><p>A robot without a serial number is still saved and listed. The app tells those robots apart by their WiFi name.</p><h2 id="my-device-wifi" tabindex="-1">My device WiFi <a class="header-anchor" href="#my-device-wifi" aria-label="Permalink to &quot;My device WiFi&quot;">​</a></h2><p>The WiFi chip in the control home&#39;s top bar shows the signal strength. Tap it to see <strong>My device WiFi</strong> — the network your device is on and whether it is the robot&#39;s network.</p><ul><li>The badge reads <code>Robot network</code> in green when your device address is in the same subnet as the robot IP. Otherwise it reads <code>Not robot network</code> in amber, with a warning that you cannot reach the robot until you join the robot AP. Both are hidden while you are connected remotely, since a remote connection does not use the robot&#39;s network.</li><li><strong>Linux desktop / Steam Deck</strong>: <code>Select WiFi</code> opens an in-app list of networks to join. <code>System settings</code> opens the OS network settings instead.</li><li><strong>Android</strong>: Android does not allow in-app scanning, so <code>System WiFi settings</code> opens the device&#39;s Wi-Fi settings screen. Pick the robot AP from the list, then press back to return to the app. The app needs location permission to show the SSID — tap the hint line to grant it. If you have already granted it and the name still does not appear, device location is off; tap the hint line to turn it on.</li><li>iOS and web builds show a note to connect from the system settings instead.</li></ul><h2 id="connection-status-in-the-top-bar" tabindex="-1">Connection status in the top bar <a class="header-anchor" href="#connection-status-in-the-top-bar" aria-label="Permalink to &quot;Connection status in the top bar {#connection-status-in-the-top-bar}&quot;">​</a></h2><p>In the control home&#39;s top bar, the status light next to the logo summarizes the connection:</p><table tabindex="0"><thead><tr><th>Light</th><th>Meaning</th></tr></thead><tbody><tr><td>Green</td><td>Everything is normal</td></tr><tr><td>Amber</td><td>Connected, but something needs attention — vision stream down, or another device holds control</td></tr><tr><td>Red, blinking fast</td><td>The robot reports a fault</td></tr><tr><td>Red</td><td>No connection to the robot</td></tr></tbody></table><p>Tap the light to open <strong>Overall system status</strong>. It lists <strong>IMU</strong>, <strong>CAN</strong>, <strong>FindPose</strong>, <strong>Control</strong>, <strong>Vision</strong>, and <strong>Ownership</strong>, each with a green or amber dot. Tap a row marked <code>Run ▸</code> to retry that step. <strong>Ownership</strong> · <code>Take ▸</code> takes control back when another device is holding it.</p><p>The control home has no disconnected banner: if the robot drops and does not come back within 8 seconds, the app returns to the Hub, which is where the status line, <code>Reconnect</code>, and <code>Switch WiFi</code> live. It also returns to the Hub the moment the connected robot changes — turning a robot off frees its WiFi, and the app may find a different robot on the robot network and connect to that one.</p><p><img src="'+n+'" alt="Overall system status"></p><blockquote><p><strong>What developer mode adds here</strong> is collected on <a href="/RBQ/nightly/manual/gui/developer-mode.html#connection">Developer mode</a>.</p></blockquote>',45)])])}const v=s(c,[["render",h]]);export{y as __pageData,v as default};
